require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/ManagementMeetingsRepository.php';Auth::requireLogin();if(!ManagementMeetingsRepository::menuAllowed()){http_response_code(403);exit('دسترسی غیرمجاز');}$u=Auth::user();if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');ManagementMeetingsRepository::archiveRule((int)($_POST['id']??0),(int)$u['id']);flash('نسخه قانون غیرفعال شد.');}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Rules page: '.$e->getMessage());flash('تغییر وضعیت قانون انجام نشد.','danger');}redirect('/admin/management-rules.php');}$filters=['active'=>isset($_GET['active'])?(string)$_GET['active']:'1','scope_type'=>trim((string)($_GET['scope_type']??'')),'scope_value'=>trim((string)($_GET['scope_value']??'')),'rule_code'=>trim((string)($_GET['rule_code']??''))];$rows=ManagementMeetingsRepository::getActiveRules($filters,$u);$print=($_GET['print']??'')==='1';$pageTitle='قوانین مصوب';$adminExtraStylesheets=['/assets/css/management-governance.css'];if(!$print)require __DIR__.'/../views/partials/admin-header.php';else {?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title><?=e($pageTitle)?></title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/admin.css"><link rel="stylesheet" href="/assets/css/management-governance.css"></head><body><?php }?>
<div class="mg-page"><header class="mg-hero"><div><small>نسخه‌های معتبر سیاست‌های داخلی</small><h1>قوانین مصوب</h1><p>قوانین فعال و سوابق نسخه‌های پیشین</p></div><div class="mg-actions no-print"><?php if(!$print):?><a class="btn" target="_blank" href="?<?=e(http_build_query(array_merge($filters,['print'=>1])))?>">چاپ / PDF</a><?php endif?></div></header><?php if(!$print)require __DIR__.'/includes/management-governance-nav.php';?><section class="card no-print"><form class="mg-filter"><label>کد قانون<input name="rule_code" value="<?=e($filters['rule_code'])?>"></label><label>دامنه<select name="scope_type"><option value="">همه</option><?php foreach(['company'=>'کل شرکت','department'=>'واحد','role'=>'نقش','sales_line'=>'لاین فروش','user'=>'کاربر'] as $k=>$v):?><option value="<?=$k?>" <?=$filters['scope_type']===$k?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label><label>مقدار دامنه<input name="scope_value" value="<?=e($filters['scope_value'])?>"></label><label>وضعیت<select name="active"><option value="1" <?=$filters['active']==='1'?'selected':''?>>فعال</option><option value="0" <?=$filters['active']==='0'?'selected':''?>>آرشیو</option><option value="" <?=$filters['active']===''?'selected':''?>>همه</option></select></label><div class="mg-actions"><button class="btn btn-primary">اعمال فیلتر</button><a class="btn" href="/admin/management-rules.php">پاکسازی</a></div></form></section><section class="mg-page"><?php foreach($rows as $r):?><article class="card mg-rule"><div class="section-heading-row"><div><small><?=e($r['rule_code'])?> · نسخه <?=format_number($r['version_number'])?></small><h2><?=e($r['title'])?></h2><p><?=e($r['meeting_title'].' / '.$r['decision_title'])?></p></div><span class="mg-badge"><?=($r['active']&&(!$r['expire_date']||$r['expire_date']>=date('Y-m-d')))?'فعال':'آرشیو / منقضی'?></span></div><div class="mg-detail-grid"><div class="mg-detail"><span>دامنه</span><strong><?=e(['company'=>'کل شرکت','department'=>'واحد','role'=>'نقش','sales_line'=>'لاین فروش','user'=>'کاربر'][$r['scope_type']]??$r['scope_type'])?> <?=e($r['scope_value']??'')?></strong></div><div class="mg-detail"><span>تاریخ اجرا</span><strong><?=e(JalaliDate::toJalali($r['effective_date']))?></strong></div><div class="mg-detail"><span>تاریخ انقضا</span><strong><?=e(JalaliDate::toJalali($r['expire_date'])?:'بدون انقضا')?></strong></div></div><p><?=nl2br(e($r['content']))?></p><div class="mg-actions no-print"><a class="btn btn-small" href="/admin/management-decision-view.php?id=<?=$r['decision_id']?>">مصوبه مرتبط</a><?php if(ManagementMeetingsRepository::canManageRules($u)&&$r['active']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small">غیرفعال‌سازی</button></form><?php endif?></div></article><?php endforeach?><?php if(!$rows):?><section class="card mg-empty">قانونی مطابق دامنه و فیلترها پیدا نشد.</section><?php endif?></section></div><?php if($print):?><script>addEventListener('load',()=>setTimeout(()=>print(),200))</script></body></html><?php else:require __DIR__.'/../views/partials/admin-footer.php';endif?>
